fields.InputDefinition:
{
  "goal": "Open the Chat application and wait for the workspace. Select the conversation named 'Membership renewal questions' from the sidebar — it is seeded with a completed AI message for this test. If it is missing, pick any other conversation that already contains an AI reply, or as a last resort send a message and wait for one. On a completed AI message, confirm the per-message action affordances render: a pin (thumbtack) button, a thumbs up/down rating control, and reaction buttons. Click the pin button and confirm its pinned state toggles (e.g. it highlights and/or a pinned-messages chip appears in the header). Seeing the message action controls render and the pin toggle respond is success. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
